package in.kabadiwala.connect.service; import in.kabadiwala.connect.model.AuditLog; import in.kabadiwala.connect.repository.AuditLogRepository; import org.springframework.stereotype.Service; import java.util.Map; @Service public class AuditService {private final AuditLogRepository r; public AuditService(AuditLogRepository r){this.r=r;} public void log(String actor,String action,String type,String id,String from,String to,Map<String,Object> meta){var a=new AuditLog();a.actorId=actor;a.action=action;a.entityType=type;a.entityId=id;a.previousStatus=from;a.newStatus=to;a.metadata=meta;r.save(a);}}
